+import { csvCell } from '../lib/text.js';
+import { createEventCard } from './event-card.js';
+import { buildRoster } from './roster.js';
+
+function csvRow(cells) {
+  return cells.map(csvCell).join(',') + '\n';
+}
+
+export function exportRosterCsv(event, signups) {
+  const card = createEventCard(event);
+  const rows = buildRoster(signups).map(({ name, email }) => csvRow([card.title, card.dateLabel, name, email]));
+  return csvRow(['event', 'date', 'name', 'email']) + rows.join('');
+}

